application.css:
* {
  box-sizing: border-box;
}

:root {
  color-scheme: light;
  --ink: #172033;
  --muted: #526071;
  --border: #c8d1dc;
  --surface: #ffffff;
  --background: #f3f6fa;
  --accent: #2457a6;
  --accent-dark: #183f7c;
  --danger: #a12929;
  --focus: #f2a900;
}

body {
  margin: 0;
  min-width: 16rem;
  background: var(--background);
  color: var(--ink);
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.5;
}

.app-shell {
  width: min(100% - 2rem, 46rem);
  margin: 0 auto;
  padding: 3rem 0 4rem;
}

.app-header {
  margin-bottom: 2rem;
}

.eyebrow {
  margin: 0 0 .35rem;
  color: var(--accent-dark);
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
}

h1, h2, p {
  margin-top: 0;
}

h1 {
  margin-bottom: .5rem;
  font-size: clamp(2rem, 7vw, 3rem);
  line-height: 1.1;
}

h2 {
  margin-bottom: 1rem;
  font-size: 1.25rem;
}

.intro {
  margin-bottom: 0;
  color: var(--muted);
}

.todo-panel, .list-section {
  padding: 1.5rem;
  border: 1px solid var(--border);
  border-radius: .75rem;
  background: var(--surface);
  box-shadow: 0 .25rem 1rem rgb(23 32 51 / 6%);
}

.list-section {
  margin-top: 1.25rem;
}

.input-row {
  display: flex;
  align-items: end;
  gap: .75rem;
}

.field-group {
  flex: 1 1 auto;
}

label {
  display: block;
  margin-bottom: .4rem;
  font-weight: 650;
}

input {
  width: 100%;
  min-height: 2.75rem;
  padding: .6rem .75rem;
  border: 1px solid #8795a6;
  border-radius: .4rem;
  color: var(--ink);
  background: var(--surface);
  font: inherit;
}

button {
  min-height: 2.75rem;
  padding: .6rem 1rem;
  border: 0;
  border-radius: .4rem;
  background: var(--accent);
  color: #fff;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}

button:hover {
  background: var(--accent-dark);
}

button:focus-visible, input:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.form-message {
  margin: .6rem 0 0;
  color: var(--danger);
  font-size: .95rem;
  font-weight: 650;
}

.list-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.list-heading h2 {
  margin-bottom: 0;
}

.count {
  margin-bottom: 0;
  color: var(--muted);
  white-space: nowrap;
}

.task-list {
  display: grid;
  gap: .7rem;
  margin-top: 1.25rem;
}

.task-item {
  display: flex;
  align-items: center;
  gap: .75rem;
  min-width: 0;
  padding: .8rem .9rem;
  border: 1px solid var(--border);
  border-radius: .45rem;
}

.task-item .task-text {
  flex: 1;
  min-width: 0;
  overflow-wrap: anywhere;
}

.task-item.completed .task-text {
  color: var(--muted);
  text-decoration: line-through;
}

.complete-control {
  width: 1.25rem;
  height: 1.25rem;
  min-height: 0;
  flex: 0 0 auto;
  padding: 0;
  accent-color: var(--accent);
}

.delete-control {
  min-height: 2rem;
  padding: .3rem .6rem;
  background: transparent;
  color: var(--danger);
  font-size: .9rem;
}

.delete-control:hover {
  background: #fcecec;
}

.empty-message {
  margin: 1.25rem 0 0;
  color: var(--muted);
  text-align: center;
}

@media (max-width:  thirtyrem) {
  .input-row {
    align-items: stretch;
    flex-direction: column;
  }
}

@media (max-width: 30rem) {
  .app-shell {
    padding-top: 2rem;
  }
  .todo-panel, .list-section {
    padding: 1rem;
  }
  .input-row {
    align-items: stretch;
    flex-direction: column;
  }
  .list-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: .25rem;
  }
}

