const form = document.querySelector('#task-form');
const input = document.querySelector('[data-testid="task-input"]');
const taskList = document.querySelector('[data-testid="task-list"]');
const countElement = document.querySelector('[data-testid="incomplete-count"]');
const emptyMessage = document.querySelector('#empty-message');
const errorMessage = document.querySelector('#task-error');

let tasks = [];
let nextTaskId = 1;

function updateSummary() {
  const incompleteCount = tasks.filter(task => !task.completed).length;
  countElement.textContent = String(incompleteCount);
  emptyMessage.hidden = tasks.length > 0;
}

function createTaskElement(task) {
  const item = document.createElement('article');
  item.className = 'task-item';
  item.dataset.testid = 'task';
  item.dataset.completed = String(task.completed);
  if (task.completed) item.classList.add('completed');

  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.className = 'complete-control';
  checkbox.dataset.testid = 'task-complete';
  checkbox.id = `task-complete-${task.id}`;
  checkbox.checked = task.completed;
  checkbox.setAttribute('aria-label', `Mark ${task.text} as complete`);
  checkbox.addEventListener('change', () => toggleTask(task.id));

  const label = document.createElement('label');
  label.className = 'task-text';
  label.dataset.testid = 'task-text';
  label.htmlFor = checkbox.id;
  label.textContent = task.text;

  const deleteButton = document.createElement('button');
  deleteButton.type = 'button';
  deleteButton.className = 'delete-control';
  deleteButton.dataset.testid = 'task-delete';
  deleteButton.textContent = 'Delete';
  deleteButton.setAttribute('aria-label', `Delete ${task.text}`);
  deleteButton.addEventListener('click', () => deleteTask(task.id));

  item.append(checkbox, label, deleteButton);
  return item;
}

function renderTasks() {
  taskList.replaceChildren(...tasks.map(createTaskElement));
  updateSummary();
}

function showValidationError() {
  errorMessage.hidden = false;
  input.setAttribute('aria-invalid', 'true');
  input.focus();
}

function clearValidationError() {
  errorMessage.hidden = true;
  input.removeAttribute('aria-invalid');
}

function addTask(event) {
  event.preventDefault();
  const text = input.value.trim();
  if (!text) {
    showValidationError();
    return;
  }
  tasks.push({ id: nextTaskId++, text, completed: false });
  input.value = '';
  clearValidationError();
  renderTasks();
  input.focus();
}

function toggleTask(id) {
  const task = tasks.find(item => item.id === id);
  if (!task) return;
  task.completed = !task.completed;
  renderTasks();
}

function deleteTask(id) {
  tasks = tasks.filter(task => task.id !== id);
  renderTasks();
}

form.addEventListener('submit', addTask);
input.addEventListener('input', () => {
  if (input.value.trim()) clearValidationError();
});
renderTasks();
